import { useState } from 'react';
import { getTelemetryTrace } from '@/pages/eventGenerator/telemetryService';
export function EventGeneratorPage() {
  const [traceError, setTraceError] = useState('');
  const refreshTrace = async () => {
    setTraceError('');
    try { await getTelemetryTrace('message-1'); } catch (error) { setTraceError(error instanceof Error ? error.message : 'Unable to load telemetry trace.'); }
  };
  return <main><h1>Publish to Hub</h1><button onClick={refreshTrace}>Refresh</button>{traceError && <aside role='alert'>{traceError}</aside>}</main>;
}

